svg.onload:
var svg = document.documentElement;

var grupy = document.querySelectorAll("g");



var widokPoczatkowy = svg.getAttribute("viewBox");

var aktywna = null;

var animacja = null;



var mapaAnimowana = document.getElementById("mapaAnimowana");

var mapaDuza = document.getElementById("mapaDuza");



// --------------------------------------------------

// ANIMACJA VIEWBOX + PRZENIKANIE MAP

// --------------------------------------------------



function animujViewBox(docelowy, zoomIn) {



    if (animacja) {

        cancelAnimationFrame(animacja);

    }



    var start = svg.getAttribute("viewBox")

        .split(/\s+/)

        .map(Number);



    var koniec = docelowy

        .split(/\s+/)

        .map(Number);



    var czasStart = performance.now();

    var czasTrwania = 700;



    function krok(czas) {



        var postep = (czas - czasStart) / czasTrwania;



        if (postep > 1) {

            postep = 1;

        }



        // Płynne przyspieszenie i zwolnienie

        var t = postep * postep * (3 - 2 * postep);



        // Animacja viewBox

        var wynik = start.map(function(wartosc, i) {

            return wartosc + (koniec[i] - wartosc) * t;

        });



        svg.setAttribute("viewBox", wynik.join(" "));



        // --------------------------------------------------

        // PRZENIKANIE MAP

        // --------------------------------------------------



        if (mapaAnimowana && mapaDuza) {



            if (zoomIn) {

                mapaAnimowana.style.opacity = 1 - t;

                mapaDuza.style.opacity = t;

            } else {

                mapaAnimowana.style.opacity = t;

                mapaDuza.style.opacity = 1 - t;

            }

        }



        if (postep < 1) {

            animacja = requestAnimationFrame(krok);

        } else {



            if (mapaAnimowana && mapaDuza) {



                if (zoomIn) {

                    mapaAnimowana.style.opacity = "0";

                    mapaDuza.style.opacity = "1";

                } else {

                    mapaAnimowana.style.opacity = "1";

                    mapaDuza.style.opacity = "0";

                }

            }

        }

    }



    animacja = requestAnimationFrame(krok);

}



// --------------------------------------------------

// OBSŁUGA KLIKALNYCH GRUP

// --------------------------------------------------



grupy.forEach(function(grupa) {



    var nazwa = grupa.getAttribute("inkscape:label");



    // Pomijamy grupy bez etykiety

    // oraz główną warstwę Inkscape

    if (!nazwa || nazwa === "Warstwa 1") {

        return;

    }



    grupa.style.cursor = "pointer";



    grupa.addEventListener("click", function() {



        // Ponowne kliknięcie aktywnej grupy

        if (aktywna === this) {



            animujViewBox(widokPoczatkowy, false);



            aktywna = null;



            return;

        }



        // Zapamiętujemy aktywną grupę

        aktywna = this;



        // Rzeczywisty obszar grupy

        var box = this.getBBox();



        // Aktualne proporcje viewBox

        var obecny = svg.getAttribute("viewBox")

            .split(/\s+/)

            .map(Number);



        var proporcja = obecny[2] / obecny[3];



        // Margines wokół kraju

        var margines = 0.25;



        var szerokosc = box.width * (1 + margines * 2);

        var wysokosc = box.height * (1 + margines * 2);



        // Dopasowanie proporcji viewBox

        if (szerokosc / wysokosc > proporcja) {

            wysokosc = szerokosc / proporcja;

        } else {

            szerokosc = wysokosc * proporcja;

        }



        // Środek grupy

        var srodekX = box.x + box.width / 2;

        var srodekY = box.y + box.height / 2;



        // Nowy obszar viewBox

        var x = srodekX - szerokosc / 2;

        var y = srodekY - wysokosc / 2;



        var nowyViewBox =

            x + " " +

            y + " " +

            szerokosc + " " +

            wysokosc;



        // Zoom + przenikanie map

        animujViewBox(nowyViewBox, true);



    });



});
